<div class="page-title"><div><em>SECURITY</em><h1>Audit log</h1><p>A complete record of administrative and account activity.</p></div></div><section class="panel audit-panel"><form class="filter audit-filter" method="get"><input name="q" value="<?=html_escape($q??'')?>" placeholder="⌕ Search action, description or email"><button class="outline" type="submit">Search</button><?php if(!empty($q)):?><a class="outline" href="<?=site_url('admin/audit_logs')?>">Clear</a><?php endif?></form><div class="data-table audit-table"><div class="tr th"><span>When</span><span>User</span><span>Action</span><span>Description</span><span>IP address</span></div><?php if($logs): foreach($logs as $l):?><div class="tr"><span class="audit-when"><b><?=date('M j, Y',strtotime($l['created_at']))?></b><small><?=date('g:i:s a',strtotime($l['created_at']))?></small></span><span class="audit-user"><b><?=$l['first_name']?html_escape($l['first_name'].' '.$l['last_name']):'System'?></b><?php if(!empty($l['email'])):?><small><?=html_escape($l['email'])?></small><?php endif?></span><span><b class="audit-action"><?=html_escape(ucwords(str_replace('_',' ',$l['action'])))?></b></span><span class="audit-description"><?=html_escape($l['description'])?></span><span class="muted-ip"><?=html_escape($l['ip_address']?:'—')?></span></div><?php endforeach; else:?><div class="audit-empty">No audit events match your search.</div><?php endif?></div></section>
